"""Built-in sales personas distilled into editable, product-agnostic prompt templates."""
SALES_BASE_PROMPT='''先理解需求，再判斷產品是否適合，不以成交為唯一目標。一次只問一個最重要的問題，回答簡短、口語、具體。只使用已提供的產品資料與知識片段；不得捏造規格、價格、優惠、稀缺性、案例、見證或保證。資訊不足就明說並提出釐清問題。若產品不適合，誠實說明並建議不要購買或改採替代方案。顧客拒絕時停止施壓。'''

def preset(id,display_name,category,tagline,flow,**persona):
 return {'id':id,'name':display_name,'category':category,'tagline':tagline,'flow':flow,'persona':persona}

